parameters.jsCode:
// Valida el contrato de entrada y arma el rango de fechas a consultar en la agenda.
const TZ = 'America/Argentina/Buenos_Aires';
const MAX_DIAS = 31; // tope técnico para no saturar el chat ni las APIs
const e = $input.first().json;
const accion = String(e.accion || '').toUpperCase().trim();
const hoy = DateTime.now().setZone(TZ).startOf('day');
const errores = [];

const fecha = (s) => {
  if (!s) return null;
  const d = DateTime.fromISO(String(s).slice(0, 10), { zone: TZ });
  return d.isValid ? d.startOf('day') : null;
};

if (!['CONSULTAR_DISPONIBILIDAD', 'RESERVAR', 'CONSULTAR_TURNOS'].includes(accion)) {
  errores.push('¿Querés consultar la disponibilidad o reservar un turno? Indicame el día (y el horario si ya lo elegiste).');
}

let fechaHora = null;
if (e.fecha_hora) {
  const fh = DateTime.fromISO(String(e.fecha_hora).slice(0, 16), { zone: TZ });
  if (fh.isValid) fechaHora = fh;
  else errores.push(`No pude interpretar la fecha y hora "${e.fecha_hora}". ¿Me la indicás nuevamente?`);
}
if (accion === 'RESERVAR' && !fechaHora && !errores.length) {
  errores.push('Para reservar necesito que me indiques el día y el horario del turno.');
}
if (accion === 'CONSULTAR_TURNOS' && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(String(e.cliente_email || '').trim())) {
  errores.push('Necesito tu correo electrónico registrado para buscar tus turnos.');
}
if (accion === 'RESERVAR' && !(e.cliente_nombre && e.cliente_apellido && e.cliente_email)) {
  errores.push('Me faltan tus datos de contacto para registrar el turno.');
}
if (!fechaHora && e.fecha_desde && !fecha(e.fecha_desde)) {
  errores.push(`No pude interpretar la fecha "${e.fecha_desde}". ¿Me la indicás nuevamente?`);
}

let desde, hasta;
if (fechaHora) {
  desde = fechaHora.startOf('day');
  hasta = desde;
} else {
  desde = fecha(e.fecha_desde) || hoy;
  hasta = fecha(e.fecha_hasta) || desde;
}
if (hasta < desde) [desde, hasta] = [hasta, desde];
if (desde < hoy) desde = hoy; // nunca se ofrecen fechas pasadas
if (hasta < desde) hasta = desde;
let recortado = false;
if (hasta.diff(desde, 'days').days > MAX_DIAS - 1) {
  hasta = desde.plus({ days: MAX_DIAS - 1 });
  recortado = true;
}

return [{ json: {
  valido: errores.length === 0,
  errores,
  accion,
  rango_desde: desde.toISODate(),
  rango_hasta: hasta.toISODate(),
  time_min: desde.toISO(),
  time_max: hasta.endOf('day').toISO(),
  fecha_hora: fechaHora ? fechaHora.toFormat("yyyy-MM-dd'T'HH:mm") : '',
  rango_recortado: recortado,
  anios: [...new Set([desde.year, hasta.year])].map((anio) => ({ anio })),
  cliente: {
    nombre: e.cliente_nombre || '',
    apellido: e.cliente_apellido || '',
    email: e.cliente_email || '',
    telefono: e.cliente_telefono || '',
  },
  session_id: e.session_id || '',
} }];

// Calcula los turnos libres: lunes a viernes, 09:00 a 17:30 (turnos de 30 min, el último termina 18:00),
// excluyendo feriados (los días "puente" SÍ se atienden), horarios pasados y horarios ocupados en Google Calendar.
const TZ = 'America/Argentina/Buenos_Aires';
const APERTURA = 9 * 60;
const ULTIMO_INICIO = 17 * 60 + 30;
const DURACION = 30;

const p = $('Validar Parámetros').first().json;
const feriadosApi = $('Consolidar Feriados').first().json.feriados || [];
const fallaFeriados = feriadosApi.find((f) => f && f.error);
if (fallaFeriados) throw new Error('API de feriados (ArgentinaDatos): ' + String(fallaFeriados.error.message ?? fallaFeriados.error));
const freeBusy = $input.first().json;
const agenda = Object.values(freeBusy.calendars || {})[0];
if (!agenda) throw new Error('Google Calendar no devolvió información de la agenda.');
if (agenda.errors && agenda.errors.length) throw new Error('Google Calendar: ' + JSON.stringify(agenda.errors));

const ocupados = (agenda.busy || []).map((b) => ({ ini: DateTime.fromISO(b.start).toMillis(), fin: DateTime.fromISO(b.end).toMillis() }));
const feriados = {};
for (const f of feriadosApi) {
  if (f && f.fecha && String(f.tipo).toLowerCase() !== 'puente') feriados[f.fecha] = f.nombre;
}

const ahora = DateTime.now().setZone(TZ);
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);
const etiquetaDia = (d) => cap(d.setLocale('es').toFormat('cccc dd/LL'));
const fechaLarga = (d) => d.setLocale('es').toFormat("cccc d 'de' LLLL 'de' yyyy");

const estadoTurno = (inicio) => {
  const minutos = inicio.hour * 60 + inicio.minute;
  if (inicio.weekday > 5) return { libre: false, motivo: 'atendemos de lunes a viernes' };
  const feriado = feriados[inicio.toISODate()];
  if (feriado) return { libre: false, motivo: `es feriado (${feriado})` };
  if (minutos < APERTURA || minutos > ULTIMO_INICIO || inicio.minute % DURACION !== 0) {
    return { libre: false, motivo: 'está fuera del horario de turnos (de 09:00 a 17:30, cada 30 minutos)' };
  }
  if (inicio <= ahora) return { libre: false, motivo: 'ese horario ya pasó' };
  const a = inicio.toMillis();
  const b = inicio.plus({ minutes: DURACION }).toMillis();
  if (ocupados.some((o) => a < o.fin && b > o.ini)) return { libre: false, motivo: 'ya está reservado' };
  return { libre: true, motivo: '' };
};

const dias = [];
const sinAtencion = [];
const hasta = DateTime.fromISO(p.rango_hasta, { zone: TZ });
for (let d = DateTime.fromISO(p.rango_desde, { zone: TZ }); d <= hasta; d = d.plus({ days: 1 })) {
  if (d.weekday > 5) continue;
  const fecha = d.toISODate();
  if (feriados[fecha]) { sinAtencion.push({ fecha, etiqueta: etiquetaDia(d), motivo: `Feriado: ${feriados[fecha]}` }); continue; }
  const horarios = [];
  for (let m = APERTURA; m <= ULTIMO_INICIO; m += DURACION) {
    const inicio = d.set({ hour: Math.floor(m / 60), minute: m % 60, second: 0, millisecond: 0 });
    if (estadoTurno(inicio).libre) horarios.push(inicio.toFormat('HH:mm'));
  }
  dias.push({ fecha, etiqueta: etiquetaDia(d), horarios });
}
const totalLibres = dias.reduce((s, d) => s + d.horarios.length, 0);

let solicitado = null;
if (p.fecha_hora) {
  const inicio = DateTime.fromISO(p.fecha_hora, { zone: TZ });
  const fin = inicio.plus({ minutes: DURACION });
  const st = estadoTurno(inicio);
  solicitado = {
    fecha_hora: p.fecha_hora,
    disponible: st.libre,
    motivo: st.motivo,
    etiqueta: `${etiquetaDia(inicio)} a las ${inicio.toFormat('HH:mm')} hs`,
    fecha_larga: fechaLarga(inicio),
    hora_inicio: inicio.toFormat('HH:mm'),
    hora_fin: fin.toFormat('HH:mm'),
    inicio_iso: inicio.toISO(),
    fin_iso: fin.toISO(),
  };
}

// ---------- Redacción del mensaje para el chat ----------
const listaDias = (lista) => lista.map((d) => `**${d.etiqueta}:** ${d.horarios.length ? d.horarios.join(' · ') : 'sin horarios disponibles'}`).join('\n');
const notaFeriados = sinAtencion.length ? '\n\n' + sinAtencion.map((f) => `🚫 ${f.etiqueta}: ${f.motivo} (no se atiende)`).join('\n') : '';
const libresDelDia = solicitado ? dias.find((d) => d.fecha === solicitado.fecha_hora.slice(0, 10)) : null;

let mensaje;
let status = 'success';
const reservar = p.accion === 'RESERVAR' && !!solicitado && solicitado.disponible;

if (solicitado && !solicitado.disponible) {
  if (p.accion === 'RESERVAR') status = 'rejected';
  const alternativas = libresDelDia && libresDelDia.horarios.length
    ? `\n\nEstos son los horarios libres de ese día:\n${listaDias([libresDelDia])}\n\n¿Querés alguno de estos o preferís consultar otra fecha?`
    : '\n\n¿Querés que consulte otra fecha?';
  mensaje = `El turno del **${solicitado.etiqueta}** no está disponible: ${solicitado.motivo}.${alternativas}`;
} else if (solicitado && p.accion === 'CONSULTAR_DISPONIBILIDAD') {
  mensaje = `¡Buenas noticias! El turno del **${solicitado.etiqueta}** (${solicitado.hora_inicio} a ${solicitado.hora_fin} hs) está disponible. ¿Querés que lo reserve a tu nombre?`;
} else if (reservar) {
  mensaje = ''; // lo redacta la plantilla de confirmación tras registrar el evento
} else if (!dias.length && !sinAtencion.length) {
  mensaje = 'El período consultado cae en fin de semana. Atendemos de **lunes a viernes de 09:00 a 18:00**. ¿Querés que consulte otra fecha?';
} else if (totalLibres === 0) {
  mensaje = `No hay horarios disponibles en el período consultado.${notaFeriados}\n\n¿Querés que consulte otra fecha?`;
} else {
  const periodo = p.rango_desde === p.rango_hasta ? 'para ese día' : 'en el período consultado';
  mensaje = `Estos son los horarios disponibles ${periodo} (turnos de 30 minutos):\n\n${listaDias(dias)}${notaFeriados}` +
    (p.rango_recortado ? '\n\n_(Te muestro como máximo 31 días.)_' : '') +
    '\n\nIndicame el día y el horario que prefieras y te lo reservo.';
}

return [{ json: {
  status,
  accion: p.accion,
  reservar,
  rango: { desde: p.rango_desde, hasta: p.rango_hasta, recortado: p.rango_recortado },
  solicitado,
  dias,
  dias_sin_atencion: sinAtencion,
  total_libres: totalLibres,
  mensaje,
} }];

