parameters.jsCode:
// Arma la lista de turnos futuros del cliente. El turno pertenece al cliente si su email figura en la descripción
// del evento (así los crea este Worker). Se devuelven solo día y hora: nunca nombre, teléfono ni otros datos del evento.
const TZ = 'America/Argentina/Buenos_Aires';
const MAX_LISTA = 10;
const p = $('Validar Parámetros').first().json;
const items = $input.all().map((i) => i.json);
const falla = items.find((e) => e && e.error);
if (falla) throw new Error('Google Calendar: ' + String(falla.error.message ?? falla.error));

const escapar = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const reEmail = new RegExp('(^|\\n)\\s*Email:\\s*' + escapar(String(p.cliente.email).trim()) + '\\s*(\\n|$)', 'i');
const ahora = DateTime.now().setZone(TZ);
const cap = (s) => s.charAt(0).toUpperCase() + s.slice(1);

const turnos = items
  .filter((e) => e && e.id && e.status !== 'cancelled' && e.start?.dateTime && reEmail.test(String(e.description ?? '')))
  .map((e) => ({
    ini: DateTime.fromISO(e.start.dateTime, { zone: TZ }),
    fin: DateTime.fromISO(e.end?.dateTime ?? e.start.dateTime, { zone: TZ }),
  }))
  .filter((t) => t.ini > ahora)
  .sort((a, b) => a.ini.toMillis() - b.ini.toMillis());

const etiqueta = (t) => `${cap(t.ini.setLocale('es').toFormat('cccc dd/LL'))} de ${t.ini.toFormat('HH:mm')} a ${t.fin.toFormat('HH:mm')} hs`;
const lista = turnos.slice(0, MAX_LISTA);
const mensaje = turnos.length
  ? `Estos son tus próximos turnos reservados:\n\n${lista.map((t) => '• ' + etiqueta(t)).join('\n')}` +
    (turnos.length > MAX_LISTA ? `\n\n_(Te muestro los próximos ${MAX_LISTA}.)_` : '')
  : 'No encontré turnos reservados a futuro con tu correo registrado. ¿Querés ver la disponibilidad o reservar uno?';

return [{ json: {
  total: turnos.length,
  turnos: lista.map((t) => ({ inicio: t.ini.toISO(), fin: t.fin.toISO(), etiqueta: etiqueta(t) })),
  mensaje,
} }];
